              isConnected ? 'status-connected' : 'status-disconnected'
            }
          >
            {isConnected ? 'connected' : 'disconnected'}
          </span>{' '}
          {isConnected ? '🟢' : '🔴'}
        </p>

        <ul className="message-list" data-testid="message-list">
          {messageList}
        </ul>

        <form className="chat-form" onSubmit={handleSubmit}>
          <input
            className="chat-input"
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            className="chat-input"
            type="text"
            placeholder="Type a message..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <button
            className="chat-button"
            type="submit"
            disabled={!isConnected}
          >
            Send
          </button>
        </form>
      </main>
    </div>
  );
};

* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen",
    "Ubuntu", "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue",
    sans-serif;
  background: #f7f7fb;
  color: #222;
}

.container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem;
}

.chat-main {
  width: 100%;
  max-width: 640px;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
}

.chat-title {
  margin: 0 0 0.5rem 0;
  font-size: 1.6rem;
}

.connection-status {
  margin: 0 0 1rem 0;
  font-size: 0.95rem;
  color: #555;
}

.status-connected {
  color: #1a8a3a;
  font-weight: 600;
}

.status-disconnected {
  color: #b00020;
  font-weight: 600;
}

.message-list {
  list-style: none;
  margin: 0 0 1rem 0;
  padding: 0.75rem;
  background: #f4f6fa;
  border: 1px solid #e2e6ef;
  border-radius: 6px;
  min-height: 200px;
  max-height: 50vh;
  overflow-y: auto;
}

.message-item {
  padding: 0.4rem 0.25rem;
  border-bottom: 1px solid #e7eaf2;
  font-size: 0.95rem;
}

.message-item:last-child {
  border-bottom: none;
}

.message-username {
  font-weight: 700;
  margin-right: 0.4rem;
  color: #345;
}

.message-text {
  word-break: break-word;
}

.chat-form {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.chat-input {
  font-size: 1rem;
  padding: 0.6rem 0.8rem;
  border: 1px solid #d0d6e1;
  border-radius: 6px;
  outline: none;
}

.chat-input:focus {
  border-color: #8a9cff;
}

.chat-button {
  font-size: 1rem;
  font-weight: 600;
  padding: 0.65rem 1rem;
  border: none;
  border-radius: 6px;
  background: #bf9900;
  color: #fff;
  cursor: pointer;
}

.chat-button:disabled {
  background: #ccc;
  cursor: not-allowed;
}
